def ft_permission_clause(text):
    low=ft_norm(text)
    if 'disclos' not in low and 'share' not in low and 'reveal' not in low and 'access' not in low:
        return False
    signals=('may disclose','may share','may reveal','may be disclosed','will disclose','will only share','only share','only disclose','reveal the information only to','restrict access to','access to confidential information by','do not apply to the disclosure','other than to its employees')
    for signal in signals:
        if signal in low:
            return True
    pos=low.find('except')
    if pos>=0:
        tail=low[pos:]
        roles=('employee','officer','director','contractor','consultant','adviser','advisor','agent','representative','affiliate','subsidiar')
        for role in roles:
            if role in tail:
                return True
    return False

def ft_clause_conditions(text):
    low=ft_norm(text)
    values=[]
    if 'need to know' in low or 'need-to-know' in low or 'strictly necessary' in low or 'absolutely necessary' in low or 'reasonably necessary' in low:
        values.append(['need_to_know',text])
    confidentiality=('bound by' in low or 'bound in writing' in low or 'bound to a duty of confidentiality' in low or 'confidentiality agreement' in low or 'obligated to protect' in low or 'obliged by their contracts' in low or 'subject to the provisions' in low or 'treat the confidential information as confidential' in low or 'in confidence' in low or 'comply with this agreement' in low)
    if confidentiality:
        values.append(['confidentiality_bound',text])
    purpose=('for the purpose' in low or 'for the permitted purpose' in low or 'to carry out the purpose' in low or 'in pursuit of the approved purpose' in low or 'involved in the performance' in low or 'directly concerned with' in low or 'to the extent necessary' in low or 'absolutely necessary for' in low)
    if purpose:
        values.append(['extent_necessary',text])
    return ft_conditions(values)

def ft_exceptions(text):
    low=ft_norm(text)
    values=[]
    authorization=('without prior written consent' in low or 'without the express written consent' in low or 'without prior written approval' in low or 'without proper written authorization' in low or 'prior written consent of the other party is given' in low or "disclosing party's prior written consent" in low)
    if authorization:
        values.append(['authorization_exception',text])
    if 'except as is required in the course of service' in low or 'except as required in the course of service' in low:
        values.append(['purpose_exception',text])
    crossref=('except as provided herein' in low or 'unless this agreement expressly permits' in low or 'except as expressly permitted by this agreement' in low)
    if crossref:
        values.append(['cross_reference_exception',text])
    pos=low.find('except')
    if pos>=0:
        tail=text[pos:]
        members=ft_recipient_classes(tail,['receiving_party'])
        if members is not None:
            norm=['permission',['receiving_party'],['disclose',['confidential_information'],members],ft_clause_conditions(text)]
            values.append(['permission_exception',norm])
    if not values:
        return ['no_exceptions']
    out=['exception_set',values[0]]
    i=1
    while i<len(values):
        out=['add_exception',out,values[i]]
        i+=1
    return out

def ft_prohibition_clause(text):
    low=ft_norm(text)
    if 'disclos' not in low and 'divulge' not in low and 'reveal' not in low and 'transfer' not in low and 'disseminat' not in low:
        return False
    if 'responsible for the performance' in low and low.find('not to disclose')>low.find('responsible for the performance'):
        return False
    signals=('shall not','will not','not to disclose','agrees not to','prohibited from disclosing','neither it nor','neither party shall','not disclose or in any way','not misuse, misappropriate, or disclose','not be disclosed')
    for signal in signals:
        if signal in low:
            return True
    return False

def ft_trigger_from(text,discloser):
    low=ft_norm(text)
    values=[]
    if 'business relationship is not entered into' in low or 'relationship is not entered into' in low:
        values.append(['relationship_nonformation_deadline'])
    if 'termination of service' in low or ('service with' in low and 'termination' in low):
        values.append(['service_termination'])
    if 'completion of the purpose' in low or 'purpose is completed' in low or 'completion of the stated purpose' in low or 'completion of purpose' in low:
        values.append(['purpose_completion'])
    relationship=('termination of the working relationship' in low or 'termination of the business relationship' in low or 'termination/expiration of the business relationship' in low or 'expiration or other termination of the project' in low or 'termination of the project' in low or 'determines not to proceed with the transaction' in low or 'ceasing to be an affiliate' in low)
    if relationship:
        values.append(['relationship_termination'])
    agreement=('termination or expiration of the agreement' in low or 'termination or expiration of this agreement' in low or 'expiration or termination of this agreement' in low or 'expiration or termination ofthis agreement' in low or 'termination/expiration of this agreement' in low or 'termination of the agreement' in low or 'termination of this agreement' in low or 'termination of this confidentiality agreement' in low or 'agreement terminates' in low)
    if agreement:
        values.append(['agreement_termination'])
    request=('upon request' in low or 'upon written request' in low or 'written request' in low or 'upon demand' in low or 'written demand' in low or 'if the disclosing party so requests' in low or 'at the request of' in low or "at sintec's request" in low)
    if request:
        values.append(['request_by',discloser])
    return ft_triggers(values)

def ft_retention_terms(text,receiver):
    low=ft_norm(text)
    out=[]
    ci=['confidential_information']
    strong=('single copy' in low and ('may retain' in low or 'may be retained' in low) or 'not be required to delete' in low or 'may retain a copy solely' in low or 'may maintain a single copy' in low)
    post_context=('return' in low or 'destroy' in low or 'delete' in low or 'erase' in low or 'notwithstanding' in low or 'following' in low or 'after' in low or strong)
    permission=('may retain' in low or 'may be retained' in low or 'entitled to retain' in low or 'may maintain a single copy' in low or 'will be entitled to retain' in low or 'not be required to delete' in low or 'legal department or outside legal counsel may maintain' in low)
    if permission and post_context:
        if 'backup' in low or 'back-up' in low or 'archival storage' in low:
            material=ci
        elif 'copy' in low or 'copies' in low or 'legal counsel' in low or 'legal department' in low:
            material=['copies_of',ci]
        else:
            material=ft_material_scope(text)
        out.append(['retention_permission',receiver,material,['after_disposal'],['retention_condition',text]])
    prohibition=False
    if post_context and ('shall be retained' in low and ('no copies' in low or 'no copy' in low)):
        prohibition=True
    if post_context and ('without retaining any copies' in low or 'without retaining copies' in low or 'no copies, electronic or otherwise' in low and 'retained' in low):
        prohibition=True
    if prohibition:
        out.append(['retention_prohibition',receiver,ft_material_scope(text),['after_disposal']])
    return out

def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    answers=inputs.get('semantic_answers',[])
    valid=[]
    available=set()
    for span in spans:
        if not isinstance(span,dict):
            continue
        uid=span.get('id')
        text=span.get('text','')
        if isinstance(uid,int) and isinstance(text,str):
            valid.append([uid,text])
            available.add(uid)
    rows=[]
    seen=set()
    unresolved=[]
    receiver=['receiving_party']
    discloser=['disclosing_party']
    ci=['confidential_information']
    found_permission=False
    found_disposal=False
    found_retention=False
    i=0
    while i<len(valid):
        uid,text=valid[i]
        low=ft_norm(text)
        if 'representative' in low and (' means ' in low or 'collectively' in low) and ('employee' in low or 'director' in low or 'officer' in low or 'agent' in low or 'adviser' in low or 'advisor' in low or 'consultant' in low or 'accountant' in low or 'attorney' in low):
            members=ft_recipient_classes(text,['party'])
            if members is not None:
                ft_add(rows,seen,['define_representative',['party'],members],[uid])
        pcontext=ft_permission_context(valid,i)
        if pcontext is not None:
            context=pcontext[0]
            support=pcontext[1]
            recipients=ft_recipient_classes(context,receiver)
            if recipients is not None:
                ft_add(rows,seen,['permission',receiver,['disclose',ci,recipients],ft_clause_conditions(context)],support)
                found_permission=True
        if ft_prohibition_clause(text):
            coordinated=('neither it nor its representatives' in low or 'neither it nor its representative' in low or 'by us, or by our agents' in low or 'we and our agents, representatives and employees' in low or 'parties and their representatives' in low)
            if coordinated:
                actor=ft_union([receiver,['representatives_of',receiver]])
            else:
                actor=receiver
            has_exception=('except' in low or 'unless' in low or 'without prior written consent' in low)
            prohibited_recipient=None
            if not has_exception:
                prohibited_recipient=ft_recipient_classes(text,receiver)
            if prohibited_recipient is None:
                if coordinated and ('any other person' in low or 'outside' in low):
                    prohibited_recipient=['outsiders_to',actor]
                else:
                    prohibited_recipient=['third_parties']
            ft_add(rows,seen,['prohibition',actor,['disclose',ci,prohibited_recipient],['no_condition'],ft_exceptions(text)],[uid])
        retention=ft_retention_terms(text,receiver)
        for term in retention:
            ft_add(rows,seen,term,[uid])
            found_retention=True
        i+=1
    i=0
    while i<len(valid):
        uid,text=valid[i]
        low=ft_norm(text)
        branch_split=('shall be returned' in low and 'upon request' in low and ('or destroyed' in low or 'or destroy' in low) and ('expiration' in low or 'termination' in low))
        if branch_split:
            material=ft_material_scope(text)
            ft_add(rows,seen,['disposal_obligation',receiver,['return_to',material,discloser],['request_by',discloser],['no_exceptions']],[uid])
            if 'project' in low or 'business relationship' in low or 'working relationship' in low:
                endpoint=['relationship_termination']
            else:
                endpoint=['agreement_termination']
            ft_add(rows,seen,['disposal_obligation',receiver,['destroy',material],endpoint,['no_exceptions']],[uid])
            found_disposal=True
            i+=1
            continue
        grouped=ft_group_clause(valid,i)
        clause=grouped[0]
        support=grouped[1]
        skip=grouped[2]
        action=ft_disposal_action(clause,receiver,discloser)
        if action is not None:
            trigger=ft_trigger_from(clause,discloser)
            if trigger is None:
                unresolved.append('Unresolved disposal trigger at source unit '+str(uid))
            else:
                exceptions=['no_exceptions']
                clow=ft_norm(clause)
                if 'may retain' in clow or 'may be retained' in clow or 'entitled to retain' in clow or 'may maintain a single copy' in clow or 'not be required to delete' in clow:
                    exceptions=['exception_set',['retention_exception',receiver,ft_material_scope(clause),['retention_condition',clause]]]
                ft_add(rows,seen,['disposal_obligation',receiver,action,trigger,exceptions],support)
                found_disposal=True
        i+=1+skip
    audits={}
    for answer in answers:
        if isinstance(answer,dict):
            operation=answer.get('operation')
            if operation in ('disclosure_permission_audit','disposal_obligation_audit','retention_effect_audit'):
                audits[operation]=answer
    specs=[['disclosure_permission_audit','no_operative_internal_or_service_permission','complete_source_no_disclosure_permission',found_permission],['disposal_obligation_audit','no_operative_disposal_obligation','complete_source_no_disposal_obligation',found_disposal],['retention_effect_audit','no_explicit_post_disposal_retention_effect','complete_source_no_retention_effect',found_retention]]
    all_ids=[]
    for uid,text in valid:
        all_ids.append(uid)
    for operation,absence_choice,constructor,found in specs:
        answer=audits.get(operation)
        if not isinstance(answer,dict):
            continue
        if answer.get('choice')==absence_choice and not found:
            inspected=ft_audit_ids(answer,available)
            if inspected and set(inspected)==set(all_ids):
                ft_add(rows,seen,[constructor],inspected)
            else:
                unresolved.append('Incomplete complete-source audit evidence: '+operation)
        elif answer.get('choice')=='category_present' and not found:
            unresolved.append('Audit reports a category whose precise clause remains unresolved: '+operation)
    clean=[]
    for item in unresolved:
        if item not in clean:
            clean.append(item)
    return {'statements':rows,'complete':len(clean)==0,'unresolved':clean}
